static int mandel(float c_re, float c_im, int count) {
    float z_re = c_re, z_im = c_im;
    int i;
    for (i = 0; i < count; ++i) {
        if (z_re * z_re + z_im * z_im > 4.f)
            break;

        float new_re = z_re * z_re - z_im * z_im;
        float new_im = 2.f * z_re * z_im;
        z_re = c_re + new_re;
        z_im = c_im + new_im;
    }

    return i;
}

static void mandelbrot_serial(float x0, float y0, float x1, float y1,
                              int width, int height, int maxIterations,
                              int output[]) {
    float dx = (x1 - x0) / width;
    float dy = (y1 - y0) / height;

    for (int j = 0; j < height; ++j) {
        for (int i = 0; i < width; ++i) {
            float x = x0 + i * dx;
            float y = y0 + j * dy;
            int index = j * width + i;
            output[index] = mandel(x, y, maxIterations);
        }
    }
}

static void mandelbrot_interleaved_static(float x0, float y0, float x1,
                                          float y1, int width, int height,
                                          int maxIterations, int output[],
                                          int threads) {
    float dx = (x1 - x0) / width;
    float dy = (y1 - y0) / height;

    #pragma omp parallel for schedule(static, 1) num_threads(threads)
    for (int j = 0; j < height; ++j) {
        float y = y0 + j * dy;
        for (int i = 0; i < width; ++i) {
            float x = x0 + i * dx;
            int index = j * width + i;
            output[index] = mandel(x, y, maxIterations);
        }
    }
}

extern "C" void run(const void* input1, const void* input2, void* output,
                     int n, int parameter, int threads) {
    const float* a = static_cast<const float*>(input1);
    const int width = n * 3 / 2;
    const int height = n;
    int* result = static_cast<int*>(output);

    if (threads <= 1) {
        mandelbrot_serial(a[0], a[1], a[2], a[3], width, height, parameter,
                          result);
    } else {
        mandelbrot_interleaved_static(a[0], a[1], a[2], a[3], width, height,
                                      parameter, result, threads);
    }
}
