17: /*
18:   These are deliberately small subsets of the main cardioid and period-2
19:   bulb.  The skip is based on an invariant for the actual float recurrence,
20:   not just on mathematical membership in a Mandelbrot component.
21: 
22:   For binary32 operations with intermediate magnitudes below 4, a primitive
23:   rounding error is at most 2^-22 in absolute value. Allowing 16 such
24:   contributions and a factor-four propagation gives less than 2^-16 in the
25:   L1 norm; eta=2^-8 is a larger per-step allowance.
26: 
27:   In the central region, s=|z.re|+|z.im| obeys
28:   s_next <= |c|_1 + s*s + eta. In the period-2 region, writing d=c+1,
29:   an iterate near -1 as z=-1+e maps near 0 with norm at most
30:   |d|_1+2|e|_1+|e|_1^2+eta; an iterate near 0 with norm b maps back
31:   near -1 with error at most |d|_1+b*b+eta. The static assertions check
32:   that the chosen bounds map strictly inside the alternating regions.
33: */
34: static bool certified_interior(float c_re, float c_im) {
35:     if (!std::isfinite(c_re) || !std::isfinite(c_im))
36:         return false;
37: 
38:     constexpr double eta = 1.0 / 256.0;
39:     constexpr double main_c_limit = 1.0 / 8.0;
40:     constexpr double main_z_limit = 1.0 / 4.0;
41:     constexpr double period_c_limit = 1.0 / 1024.0;
42:     constexpr double near_minus_one_limit = 1.0 / 64.0;
43:     constexpr double near_zero_limit = 1.0 / 16.0;
44: 
45:     static_assert(main_c_limit + main_z_limit * main_z_limit + eta <
46:                   main_z_limit, "central invariant must be strict");
47:     static_assert(period_c_limit + 2.0 * near_minus_one_limit +
48:                       near_minus_one_limit * near_minus_one_limit + eta <
49:                   near_zero_limit,
50:                   "period-2 transition to zero must be strict");
51:     static_assert(period_c_limit + near_zero_limit * near_zero_limit + eta <
52:                   near_minus_one_limit,
53:                   "period-2 transition to minus one must be strict");
54: 
55:     const double re = static_cast<double>(c_re);
56:     const double im = static_cast<double>(c_im);
57:     if (std::fabs(re) + std::fabs(im) <= main_c_limit)
58:         return true;
59: 
60:     return std::fabs(re + 1.0) + std::fabs(im) <= period_c_limit;
61: }
