63: static int mandel(float c_re, float c_im, int count) {
64:     if (count > 0 && certified_interior(c_re, c_im))
65:         return count;
66: 
67:     float z_re = c_re, z_im = c_im;
68:     float checkpoint_re = 0.0f, checkpoint_im = 0.0f;
69:     std::uint64_t power = 1, distance = 0;
70:     bool have_checkpoint = false;
71:     int i;
72: 
73:     for (i = 0; i < count; ++i) {
74:         if (z_re * z_re + z_im * z_im > 4.f)
75:             break;
76: 
77:         if (std::isfinite(z_re) && std::isfinite(z_im)) {
78:             if (!have_checkpoint) {
79:                 checkpoint_re = z_re;
80:                 checkpoint_im = z_im;
81:                 power = 1;
82:                 distance = 0;
83:                 have_checkpoint = true;
84:             } else {
85:                 if (same_float_bits(z_re, checkpoint_re) &&
86:                     same_float_bits(z_im, checkpoint_im))
87:                     return count;
88: 
89:                 ++distance;
90:                 if (distance == power) {
91:                     checkpoint_re = z_re;
92:                     checkpoint_im = z_im;
93:                     if (power <= UINT64_MAX / 2)
94:                         power *= 2;
95:                     distance = 0;
96:                 }
97:             }
98:         } else {
99:             have_checkpoint = false;
100:             power = 1;
101:             distance = 0;
102:         }
103: 
104:         float new_re = z_re * z_re - z_im * z_im;
105:         float new_im = 2.f * z_re * z_im;
106:         float next_re = c_re + new_re;
107:         float next_im = c_im + new_im;
108:         z_re = next_re;
109:         z_im = next_im;
110:     }
111: 
112:     return i;
113: }
