115: void mandelbrot_serial(float x0, float y0, float x1, float y1, int width, int height, int maxIterations, int output[]) {
116:     float dx = (x1 - x0) / width;
117:     float dy = (y1 - y0) / height;
118: 
119:     for (int j = 0; j < height; j++) {
120:         for (int i = 0; i < width; ++i) {
121:             float x = x0 + i * dx;
122:             float y = y0 + j * dy;
123: 
124:             int index = (j * width + i);
125:             output[index] = mandel(x, y, maxIterations);
126:         }
127:     }
128: }
